fn argmin(a: Vec<i8>) -> usize {
    assert!(!a.is_empty(), "Input vector must be non-empty");

    // Start by assuming the first element is the minimum.
    let mut min_idx = 0;
    let mut min_val = a[0];

    // Scan the rest of the array.
    for (i, &value) in a.iter().enumerate().skip(1) {
        if value < min_val {
            min_val = value;
            min_idx = i;
        }
    }

    min_idx
}

fn main() {
    // Some quick tests:
    let v1 = vec![3, 1, 4, 1, 5];
    assert_eq!(argmin(v1), 1);

    let v2 = vec![-2, -3, -3, 0];
    assert_eq!(argmin(v2), 1);

    let v3 = vec![7];
    assert_eq!(argmin(v3), 0);

    println!("All tests passed!");
}